begin;
create extension if not exists pgtap with schema extensions;
select plan(10);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at) values('00000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000000','authenticated','authenticated','public-flow@test.local','',now(),now(),now());
insert into public.organizations(id,name) values('10000000-0000-0000-0000-000000000041','Public Org');insert into public.organization_members(organization_id,user_id,role) values('10000000-0000-0000-0000-000000000041','00000000-0000-0000-0000-000000000041','OWNER');
insert into public.locations(id,organization_id,name,slug) values('20000000-0000-0000-0000-000000000041','10000000-0000-0000-0000-000000000041','Public Location','public-location');
insert into public.flows(id,location_id,name,slug) values('70000000-0000-0000-0000-000000000041','20000000-0000-0000-0000-000000000041','Public Flow','menu');insert into public.flow_versions(id,flow_id,version_number) values('71000000-0000-0000-0000-000000000041','70000000-0000-0000-0000-000000000041',1);
insert into public.flow_nodes(id,flow_version_id,type,config) values('72000000-0000-0000-0000-000000000041','71000000-0000-0000-0000-000000000041','START','{}'),('72000000-0000-0000-0000-000000000042','71000000-0000-0000-0000-000000000041','TEXT','{"title":"Welcome"}'),('72000000-0000-0000-0000-000000000043','71000000-0000-0000-0000-000000000041','END','{}');insert into public.flow_edges(id,flow_version_id,source_node_id,target_node_id) values('73000000-0000-0000-0000-000000000041','71000000-0000-0000-0000-000000000041','72000000-0000-0000-0000-000000000041','72000000-0000-0000-0000-000000000042'),('73000000-0000-0000-0000-000000000042','71000000-0000-0000-0000-000000000041','72000000-0000-0000-0000-000000000042','72000000-0000-0000-0000-000000000043');update public.flow_versions set status='PUBLISHED',published_at=now() where id='71000000-0000-0000-0000-000000000041';update public.flows set published_version_id='71000000-0000-0000-0000-000000000041' where id='70000000-0000-0000-0000-000000000041';
select ok(not has_table_privilege('anon','public.flow_sessions','select'),'anon still cannot select sessions');select ok(has_function_privilege('anon','public.get_public_flow(text,text)','execute'),'anon has only scoped public RPC');
set local role anon;
select is((public.get_public_flow('missing','menu') is null),true,'unavailable flow is indistinguishable');select is(public.get_public_flow('public-location','menu')->>'versionId','71000000-0000-0000-0000-000000000041','published definition is projected');
select throws_ok($$select public.start_public_flow_session('public-location','menu','72000000-0000-0000-0000-000000000043','{"completed":false}')$$,'22023','INVALID_PUBLIC_ACTION','cannot forge initial node');
create temporary table public_result as select public.start_public_flow_session('public-location','menu','72000000-0000-0000-0000-000000000042','{"render":{"type":"TEXT"},"completed":false}') value;
select is(length(value->>'publicToken'),64,'opaque 256-bit token is returned') from public_result;select is(value->>'status','ACTIVE','public session starts active') from public_result;select is(public.get_public_flow_session((select value->>'publicToken' from public_result))->>'revision','0','token retrieves only its session');select is(public.get_public_flow_session('ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff') is null,true,'invalid token reveals nothing');
reset role;select ok((select expires_at>now() and expires_at<=now()+interval '46 minutes' from public.flow_sessions order by started_at desc limit 1),'session receives 45 minute TTL');
select * from finish();rollback;
